package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.AuditLog
import java.util.Collections
import java.util.Date
import java.util.WeakHashMap
import org.bson.Document

/** Keeps audit-log rows in the database, through the MongoDB driver. Every write is stored at once. */
class MongoAuditLogRepository(private val db: Db) : AuditLogRepository {
    private val collection = "audit-log"

    /** The fields a change may write */
    private val fields = listOf("at", "by")

    override fun findById(id: String): AuditLog? {
        return db.find(collection, Document("_id", id), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<AuditLog> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun insert(entity: AuditLog): AuditLog {
        db.insert("AuditLog", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: AuditLog): AuditLog {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("AuditLog", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: AuditLog): Unit {
        db.delete("AuditLog", collection, Document("_id", entity.id!!))
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): AuditLog {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a AuditLog: what is null is left out. */
    private fun toDocument(value: AuditLog): Document {
        val document = Document()
        value.id?.let { document["_id"] = it }
        value.at?.let { document["at"] = Date.from(it) }
        value.by?.let { document["by"] = it }
        return document
    }

    private fun fromDocument(document: Document): AuditLog =
        AuditLog(
            id = document["_id"] as String?,
            at = (document["at"] as Date?)?.toInstant(),
            by = document["by"],
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<AuditLog, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

