package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Product
import java.util.Collections
import java.util.Date
import java.util.UUID
import java.util.WeakHashMap
import org.bson.Document
import org.bson.types.Binary
import org.bson.types.Decimal128
import org.bson.types.ObjectId

/** Keeps products rows in the database, through the MongoDB driver. Every write is stored at once. */
class MongoProductRepository(private val db: Db) : ProductRepository {
    private val collection = "products"

    /** The fields a change may write */
    private val fields = listOf("sku", "price", "stock", "weight", "big", "created", "reference", "picture", "key", "pattern", "patterns", "text", "parts", "low")

    override fun findById(id: String): Product? {
        if (!ObjectId.isValid(id)) return null
        return db.find(collection, Document("_id", ObjectId(id)), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Product> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun insert(entity: Product): Product {
        entity.id = entity.id ?: ObjectId().toHexString()
        db.insert("Product", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Product): Product {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Product", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Product): Unit {
        db.delete("Product", collection, Document("_id", ObjectId(entity.id!!)))
    }

    override fun addPattern(id: String, pattern: Any): Product? {
        if (!ObjectId.isValid(id)) return null
        val change = Document("\$push", Document("patterns", pattern))
        return db.change("Product", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removePattern(id: String, position: Int, size: Int): Product? {
        if (!ObjectId.isValid(id)) return null
        val head = Document("\$slice", listOf("\$patterns", position))
        val tail = Document("\$slice", listOf("\$patterns", position + 1, maxOf(size, 1)))
        val change = listOf(Document("\$set", Document("patterns", Document("\$concatArrays", listOf(head, tail)))))
        return db.rewrite("Product", collection, Document("_id", ObjectId(id)).append("patterns", Document("\$size", size)), change)?.let { loaded(it) }
    }

    override fun addPart(id: String, part: Product.Part): Product? {
        if (!ObjectId.isValid(id)) return null
        val change = Document("\$push", Document("parts", partToDocument(part)))
        return db.change("Product", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removePart(id: String, position: Int, size: Int): Product? {
        if (!ObjectId.isValid(id)) return null
        val head = Document("\$slice", listOf("\$parts", position))
        val tail = Document("\$slice", listOf("\$parts", position + 1, maxOf(size, 1)))
        val change = listOf(Document("\$set", Document("parts", Document("\$concatArrays", listOf(head, tail)))))
        return db.rewrite("Product", collection, Document("_id", ObjectId(id)).append("parts", Document("\$size", size)), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Product {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Product: what is null is left out. */
    private fun toDocument(value: Product): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.sku?.let { document["sku"] = it }
        value.price?.let { document["price"] = Decimal128(it) }
        value.stock?.let { document["stock"] = it }
        value.weight?.let { document["weight"] = it }
        value.big?.let { document["big"] = it }
        value.created?.let { document["created"] = Date.from(it) }
        value.reference?.let { document["reference"] = it }
        value.picture?.let { document["picture"] = Binary(it) }
        value.key?.let { document["key"] = it }
        value.pattern?.let { document["pattern"] = it }
        value.patterns?.let { document["patterns"] = it }
        value.text?.let { document["text"] = it }
        value.parts?.let { held -> document["parts"] = held.map { partToDocument(it) } }
        value.low?.let { document["low"] = it }
        return document
    }

    private fun fromDocument(document: Document): Product =
        Product(
            id = document["_id"]?.toString(),
            sku = document["sku"] as String?,
            price = Documents.decimal(document["price"]),
            stock = (document["stock"] as Number?)?.toDouble(),
            weight = (document["weight"] as Number?)?.toDouble(),
            big = (document["big"] as Number?)?.toLong(),
            created = (document["created"] as Date?)?.toInstant(),
            reference = document["reference"] as UUID?,
            picture = (document["picture"] as Binary?)?.data,
            key = document["key"] as UUID?,
            pattern = document["pattern"],
            patterns = (document["patterns"] as List<*>?)?.filterNotNull(),
            text = document["text"] as String?,
            parts = (document["parts"] as List<*>?)?.mapNotNull { (it as Document?)?.let { partFromDocument(it) } },
            low = (document["low"] as Number?)?.toLong(),
        )

    /** The document of a Product.Part: what is null is left out. */
    private fun partToDocument(value: Product.Part): Document {
        val document = Document()
        value.name?.let { document["name"] = it }
        value.inner?.let { document["inner"] = partInnerToDocument(it) }
        return document
    }

    private fun partFromDocument(document: Document): Product.Part =
        Product.Part(
            name = document["name"] as String?,
            inner = (document["inner"] as Document?)?.let { partInnerFromDocument(it) },
        )

    /** The document of a Product.Part.Inner: what is null is left out. */
    private fun partInnerToDocument(value: Product.Part.Inner): Document {
        val document = Document()
        value.deep?.let { document["deep"] = it }
        return document
    }

    private fun partInnerFromDocument(document: Document): Product.Part.Inner =
        Product.Part.Inner(
            deep = document["deep"],
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Product, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

