package app.services

import app.UnitOfWork
import app.common.Page
import app.dtos.AuditLogCreate
import app.dtos.AuditLogRead
import app.dtos.AuditLogUpdate
import app.entities.AuditLog
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.time.Instant

/** Operations on audit-log. Repositories commit every write. */
class AuditLogService(private val unitOfWork: UnitOfWork) {
    /** Stores a new AuditLog after checking it. */
    fun createAuditLog(data: AuditLogCreate): AuditLogRead {
        val values = mapOf(
            "id" to data.id,
            "at" to data.at,
            "by" to data.by,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = AuditLog()
            applyValues(entity, values)
            read(uow.auditLog.insert(entity))
        }
    }

    /** The AuditLog with this key; NotFoundException when there is none. */
    fun getAuditLog(id: String): AuditLogRead = read(find(unitOfWork, id))

    /** A page of audit-log, by primary key. */
    fun listAuditLogs(offset: Int, limit: Int): Page<AuditLogRead> = unitOfWork.auditLog.list(offset, limit).map { read(it) }

    /** Changes the given values of a AuditLog. */
    fun updateAuditLog(id: String, changes: AuditLogUpdate): AuditLogRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.auditLog.update(current))
        }
    }

    /** Deletes a AuditLog. */
    fun deleteAuditLog(id: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.auditLog.delete(current)
        }
    }

    /** Checks the values against the rules of the "audit-log" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: AuditLog?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["id"]
            if (value == null) {
                if (creating || "id" in values) errors += FieldError("_id", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("AuditLog", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: AuditLog?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: AuditLog, values: Map<String, Any?>) {
        if ("id" in values) entity.id = values["id"] as String?
        if ("at" in values) entity.at = values["at"] as Instant?
        if ("by" in values) entity.by = values["by"] as Any?
    }

    /** The AuditLog with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): AuditLog =
        uow.auditLog.findById(id) ?: throw NotFoundException("AuditLog", id)

    /** The AuditLog as services return it. */
    private fun read(entity: AuditLog): AuditLogRead =
        AuditLogRead(
            id = entity.id!!,
            at = entity.at,
            by = entity.by,
        )

    /** The values an update gives, by field. */
    private fun given(changes: AuditLogUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.at.isPresent) values["at"] = changes.at.value
        if (changes.by.isPresent) values["by"] = changes.by.value
        return values
    }
}

