package app.services

import app.UnitOfWork
import app.common.Page
import app.dtos.ProductCreate
import app.dtos.ProductRead
import app.dtos.ProductUpdate
import app.entities.Product
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.math.BigDecimal
import java.time.Instant
import java.util.UUID

/** Operations on products. Repositories commit every write. */
@Suppress("UNCHECKED_CAST")
class ProductService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Product after checking it. */
    fun createProduct(data: ProductCreate): ProductRead {
        val values = mapOf(
            "sku" to data.sku,
            "price" to data.price,
            "stock" to data.stock,
            "weight" to data.weight,
            "big" to data.big,
            "created" to data.created,
            "reference" to data.reference,
            "picture" to data.picture,
            "key" to data.key,
            "pattern" to data.pattern,
            "patterns" to data.patterns,
            "text" to data.text,
            "parts" to data.parts,
            "low" to data.low,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Product()
            applyValues(entity, values)
            read(uow.products.insert(entity))
        }
    }

    /** The Product with this key; NotFoundException when there is none. */
    fun getProduct(id: String): ProductRead = read(find(unitOfWork, id))

    /** A page of products, by primary key. */
    fun listProducts(offset: Int, limit: Int): Page<ProductRead> = unitOfWork.products.list(offset, limit).map { read(it) }

    /** Changes the given values of a Product. */
    fun updateProduct(id: String, changes: ProductUpdate): ProductRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.products.update(current))
        }
    }

    /** Deletes a Product. */
    fun deleteProduct(id: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.products.delete(current)
        }
    }

    /** Adds an item to patterns. */
    fun addPattern(id: String, pattern: Any): ProductRead {
        return unitOfWork.transaction { uow ->
            find(uow, id)
            read(uow.products.addPattern(id, pattern) ?: throw NotFoundException("Product", id))
        }
    }

    /** Removes an item from patterns, by its position. */
    fun removePattern(id: String, position: Int): ProductRead {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (position !in current.patterns.orEmpty().indices) throw NotFoundException("Pattern", position)
            read(uow.products.removePattern(id, position, current.patterns.orEmpty().size) ?: throw ConflictException("Product", "was changed by someone else since it was read", listOf("patterns")))
        }
    }

    /** Adds an item to parts. */
    fun addPart(id: String, part: Product.Part): ProductRead {
        val errors = mutableListOf<FieldError>()
        checkPart(part, "parts", errors)
        if (errors.isNotEmpty()) throw ValidationFailedException("Product", errors)
        return unitOfWork.transaction { uow ->
            find(uow, id)
            read(uow.products.addPart(id, part) ?: throw NotFoundException("Product", id))
        }
    }

    /** Removes an item from parts, by its position. */
    fun removePart(id: String, position: Int): ProductRead {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (position !in current.parts.orEmpty().indices) throw NotFoundException("Part", position)
            read(uow.products.removePart(id, position, current.parts.orEmpty().size) ?: throw ConflictException("Product", "was changed by someone else since it was read", listOf("parts")))
        }
    }

    /** Checks the values against the rules of the "products" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Product?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["parts"]
            if (value != null) {
                val document = value as List<Product.Part>
                document.forEachIndexed { i0, item0 ->
                    checkPart(item0, "parts" + "." + i0, errors)
                }
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Product", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Product?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Product, values: Map<String, Any?>) {
        if ("sku" in values) entity.sku = values["sku"] as String?
        if ("price" in values) entity.price = values["price"] as BigDecimal?
        if ("stock" in values) entity.stock = values["stock"] as Double?
        if ("weight" in values) entity.weight = values["weight"] as Double?
        if ("big" in values) entity.big = values["big"] as Long?
        if ("created" in values) entity.created = values["created"] as Instant?
        if ("reference" in values) entity.reference = values["reference"] as UUID?
        if ("picture" in values) entity.picture = values["picture"] as ByteArray?
        if ("key" in values) entity.key = values["key"] as UUID?
        if ("pattern" in values) entity.pattern = values["pattern"] as Any?
        if ("patterns" in values) entity.patterns = values["patterns"] as List<Any>?
        if ("text" in values) entity.text = values["text"] as String?
        if ("parts" in values) entity.parts = values["parts"] as List<Product.Part>?
        if ("low" in values) entity.low = values["low"] as Long?
    }

    /** The Product with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): Product =
        uow.products.findById(id) ?: throw NotFoundException("Product", id)

    /** The Product as services return it. */
    private fun read(entity: Product): ProductRead =
        ProductRead(
            id = entity.id!!,
            sku = entity.sku,
            price = entity.price,
            stock = entity.stock,
            weight = entity.weight,
            big = entity.big,
            created = entity.created,
            reference = entity.reference,
            picture = entity.picture,
            key = entity.key,
            pattern = entity.pattern,
            patterns = entity.patterns,
            text = entity.text,
            parts = entity.parts,
            low = entity.low,
        )

    /** The values an update gives, by field. */
    private fun given(changes: ProductUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.sku.isPresent) values["sku"] = changes.sku.value
        if (changes.price.isPresent) values["price"] = changes.price.value
        if (changes.stock.isPresent) values["stock"] = changes.stock.value
        if (changes.weight.isPresent) values["weight"] = changes.weight.value
        if (changes.big.isPresent) values["big"] = changes.big.value
        if (changes.created.isPresent) values["created"] = changes.created.value
        if (changes.reference.isPresent) values["reference"] = changes.reference.value
        if (changes.picture.isPresent) values["picture"] = changes.picture.value
        if (changes.key.isPresent) values["key"] = changes.key.value
        if (changes.pattern.isPresent) values["pattern"] = changes.pattern.value
        if (changes.patterns.isPresent) values["patterns"] = changes.patterns.value
        if (changes.text.isPresent) values["text"] = changes.text.value
        if (changes.parts.isPresent) values["parts"] = changes.parts.value
        if (changes.low.isPresent) values["low"] = changes.low.value
        return values
    }

    /** What a Product.Part does not follow of its rules, each with the path of its field. */
    private fun checkPart(value: Product.Part, path: String, errors: MutableList<FieldError>) {
        value.inner.let { held ->
            if (held != null) {
                checkPartInner(held, path + ".inner", errors)
            }
        }
    }

    /** What a Product.Part.Inner does not follow of its rules, each with the path of its field. */
    @Suppress("UNUSED_PARAMETER")
    private fun checkPartInner(value: Product.Part.Inner, path: String, errors: MutableList<FieldError>) {
    }
}

