package app

import app.entities.AuditLog
import app.entities.Product
import java.math.BigDecimal
import java.time.Instant
import java.time.LocalDateTime
import java.time.ZoneOffset
import java.util.UUID

/** Rows for the tests: valid values for every column, and the rows they point to. */
object Factories {
    /** A valid Product that is not stored yet; n makes its unique values differ. */
    fun newProduct(n: Int): Product =
        Product(
            sku = "sku-$n",
            price = BigDecimal("${n % 10000}.50"),
            stock = n + 0.5,
            weight = n + 0.5,
            big = n.toLong(),
            created = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
            reference = UUID.fromString("00000000-0000-4000-8000-%012d".format(n)),
            picture = byteArrayOf(n.toByte()),
            key = UUID.fromString("00000000-0000-4000-8000-%012d".format(n)),
            pattern = mapOf("n" to n),
            patterns = emptyList(),
            text = "text-$n",
            parts = listOf(newProductPart(n)),
            low = n.toLong(),
        )

    /** A stored Product. */
    fun addProduct(uow: UnitOfWork, n: Int): Product {
        val entity = newProduct(n)
        return uow.products.insert(entity)
    }

    /** A valid Product.Part; n makes its values differ. */
    fun newProductPart(n: Int): Product.Part =
        Product.Part(
            name = "name-$n",
            inner = newProductPartInner(n),
        )

    /** A valid Product.Part.Inner; n makes its values differ. */
    fun newProductPartInner(n: Int): Product.Part.Inner =
        Product.Part.Inner(
            deep = mapOf("n" to n),
        )

    /** A valid AuditLog that is not stored yet; n makes its unique values differ. */
    fun newAuditLog(n: Int): AuditLog =
        AuditLog(
            id = "id-$n",
            at = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
            by = mapOf("n" to n),
        )

    /** A stored AuditLog. */
    fun addAuditLog(uow: UnitOfWork, n: Int): AuditLog {
        val entity = newAuditLog(n)
        return uow.auditLog.insert(entity)
    }
}

