package app

import app.entities.Product
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/** The repository of the "products" table, against the test database. */
class ProductRepositoryTest {
    /** The repositories over the test database, opened empty for every test */
    private lateinit var uow: MongoUnitOfWork

    @BeforeTest
    fun open() {
        uow = TestDatabase.open()
    }

    @AfterTest
    fun close() {
        uow.db.close()
    }

    @Test
    fun isStoredAndReadBack() {
        val stored = Factories.addProduct(uow, 1)
        val found = uow.products.findById(stored.id!!)
        assertNotNull(found)
        assertEquals(stored.id, found.id)
    }

    @Test
    fun listsRowsByKey() {
        Factories.addProduct(uow, 1)
        Factories.addProduct(uow, 2)
        val page = uow.products.list(0, 1)
        assertEquals(2L, page.total)
        assertEquals(1, page.items.size)
    }

    @Test
    fun storesTheChanges() {
        val stored = Factories.addProduct(uow, 1)
        stored.sku = "changed"
        uow.products.update(stored)
        assertEquals("changed", uow.products.findById(stored.id!!)?.sku)
    }

    @Test
    fun isDeleted() {
        val stored = Factories.addProduct(uow, 1)
        uow.products.delete(stored)
        assertNull(uow.products.findById(stored.id!!))
    }

    @Test
    fun addsAndRemovesOneItemOfPatterns() {
        val n = 7
        val stored = Factories.addProduct(uow, 1)
        val before = stored.patterns.orEmpty().size
        val item: Any = mapOf("n" to n)
        val added = uow.products.addPattern(stored.id!!, item)!!
        assertEquals(before + 1, added.patterns.orEmpty().size)
        val removed = uow.products.removePattern(stored.id!!, before, added.patterns.orEmpty().size)!!
        assertEquals(before, removed.patterns.orEmpty().size)
        assertNull(uow.products.removePattern(stored.id!!, 0, before + 5))
    }

    @Test
    fun addsAndRemovesOneItemOfParts() {
        val n = 7
        val stored = Factories.addProduct(uow, 1)
        val before = stored.parts.orEmpty().size
        val item: Product.Part = Factories.newProductPart(n)
        val added = uow.products.addPart(stored.id!!, item)!!
        assertEquals(before + 1, added.parts.orEmpty().size)
        val removed = uow.products.removePart(stored.id!!, before, added.parts.orEmpty().size)!!
        assertEquals(before, removed.parts.orEmpty().size)
        assertNull(uow.products.removePart(stored.id!!, 0, before + 5))
    }
}

