package app

import app.common.Patch
import app.dtos.ProductCreate
import app.dtos.ProductUpdate
import app.entities.Product
import app.errors.NotFoundException
import app.services.ProductService
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/** The service of the "products" table, on the in-memory repositories. */
class ProductServiceTest {
    private lateinit var uow: MemoryUnitOfWork

    @BeforeTest
    fun open() {
        uow = MemoryUnitOfWork()
    }

    @Test
    fun createsAValidRow() {
        val service = ProductService(uow)
        val row = Factories.newProduct(1)
        val created = service.createProduct(createOf(row))
        val found = service.getProduct(created.id)
        assertEquals(created.id, found.id)
    }

    @Test
    fun saysWhenARowIsMissing() {
        val service = ProductService(uow)
        assertFailsWith<NotFoundException> { service.getProduct("ffffffffffffffffffffffff") }
    }

    @Test
    fun changesARow() {
        val service = ProductService(uow)
        val row = Factories.newProduct(1)
        val created = service.createProduct(createOf(row))
        val updated = service.updateProduct(created.id, ProductUpdate(sku = Patch.of("changed")))
        assertEquals("changed", updated.sku)
    }

    @Test
    fun deletesARow() {
        val service = ProductService(uow)
        val row = Factories.newProduct(1)
        val created = service.createProduct(createOf(row))
        service.deleteProduct(created.id)
        assertFailsWith<NotFoundException> { service.getProduct(created.id) }
    }

    @Test
    fun addsAndRemovesOneItemOfPatterns() {
        val n = 7
        val service = ProductService(uow)
        val row = Factories.newProduct(1)
        val created = service.createProduct(createOf(row))
        val before = created.patterns.orEmpty().size
        val item: Any = mapOf("n" to n)
        val added = service.addPattern(created.id, item)
        assertEquals(before + 1, added.patterns.orEmpty().size)
        val removed = service.removePattern(created.id, before)
        assertEquals(before, removed.patterns.orEmpty().size)
        assertFailsWith<NotFoundException> { service.removePattern(created.id, 99) }
    }

    @Test
    fun addsAndRemovesOneItemOfParts() {
        val n = 7
        val service = ProductService(uow)
        val row = Factories.newProduct(1)
        val created = service.createProduct(createOf(row))
        val before = created.parts.orEmpty().size
        val item: Product.Part = Factories.newProductPart(n)
        val added = service.addPart(created.id, item)
        assertEquals(before + 1, added.parts.orEmpty().size)
        val removed = service.removePart(created.id, before)
        assertEquals(before, removed.parts.orEmpty().size)
        assertFailsWith<NotFoundException> { service.removePart(created.id, 99) }
    }

    /** The create DTO of a row the factories made. */
    private fun createOf(row: Product) = ProductCreate(
        sku = row.sku,
        price = row.price,
        stock = row.stock,
        weight = row.weight,
        big = row.big,
        created = row.created,
        reference = row.reference,
        picture = row.picture,
        key = row.key,
        pattern = row.pattern,
        patterns = row.patterns,
        text = row.text,
        parts = row.parts,
        low = row.low,
    )
}

